use super::*;
use std::time::{Duration,Instant};
#[tokio::test]
#[ignore="explicit scoped duration and quota qualification"]
async fn sustained_scoped_capture_window(){
 let root=std::path::PathBuf::from(std::env::var("CG_QA_TEST_EVIDENCE_DIR").expect("evidence directory"));let dir=root.join(format!("sustained-peer-{}",std::process::id()));std::fs::create_dir(&dir).unwrap();let wall=||std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis()as u64;
 let ctx=common::qa_trace_scope::TraceContext{native_session_id:"native_sustained".into(),claim_id:"claim_sustained".into(),handoff_binding_id:"handoff_sustained".into(),rental_session_id:Some("rental_sustained".into()),connection_nonce:"e".repeat(32),generation:1,authority_expires_ms:wall()+120000};let state=dir.join("rental.json");std::fs::write(&state,serde_json::json!({"PcId":"2","ClaimId":"claim_sustained","RentalSessionId":"rental_sustained"}).to_string()).unwrap();
 let capture=super::super::scoped::ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();let o=observer_scoped(capture.clone());let sink=Arc::new(Sink::default());let writer=o.bind_local_stream(&info(),sink.clone()).await;
 for i in 0..3{let mut p=packet();p.header.timestamp=i*3000;writer.write(&p,&Attributes::new()).await.unwrap();}
 let request=common::qa_trace_scope::TraceRequest{context:ctx,request_nonce:"f".repeat(32),expires_ms:wall()+5000,duration_ms:60000};std::fs::write(dir.join("request.json"),serde_json::to_vec(&request).unwrap()).unwrap();tokio::time::timeout(Duration::from_secs(3),async{while capture.acquire().is_none(){tokio::time::sleep(Duration::from_millis(10)).await;}}).await.unwrap();
 let start=Instant::now();let mut calls=Vec::new();let mut count=0usize;
 // 18,000packet writes at400pps =45s, deliberately belowpredeclared45,000eventscreen.
 for batch in 0..900u32{tokio::time::sleep_until(tokio::time::Instant::from_std(start+Duration::from_millis(batch as u64*50))).await;let p=Packet{header:Header{version:2,ssrc:42,payload_type:98,timestamp:90000+batch*4500,..Default::default()},payload:Bytes::from(vec![0x55u8;1200])};let samples=crate::transport::webrtc::recovery_frame::attach(vec![p;20],2);for mut sample in samples{sample.packet.header.sequence_number=count as u16;sample.packet.header.marker=sample.index+1==sample.count;let at=Instant::now();writer.write(&sample.packet,&sample.attributes()).await.unwrap();calls.push(at.elapsed().as_nanos());count+=1;}}
 let media_elapsed_ms=start.elapsed().as_millis();o.close().await.unwrap();let trace=dir.join(format!("capture-{}.jsonl","f".repeat(32)));let deadline=Instant::now()+Duration::from_secs(3);let footer=loop{let text=std::fs::read_to_string(&trace).unwrap();if let Some(f)=text.lines().last().and_then(|s|serde_json::from_str::<serde_json::Value>(s).ok()){if f["type"]=="footer"{break f;}}assert!(Instant::now()<deadline);tokio::time::sleep(Duration::from_millis(20)).await;};calls.sort_unstable();assert_eq!(count,18000);assert_eq!(sink.packets.lock().unwrap().len(),18003);
 let result=serde_json::json!({"packets":count,"frames":900,"events":footer["written"],"footer":footer,"producer_p99_ns":calls[(calls.len()-1)*99/100],"producer_max_ns":calls.last(),"media_elapsed_ms":media_elapsed_ms,"file_bytes":std::fs::metadata(&trace).unwrap().len(),"trace_file":trace,"scope":"45second400pps scoped worker+filewriter load; counting test sink stores packets, no codec/network","no_rental":true,"physical_overhead_qualified":false});let f=std::fs::OpenOptions::new().write(true).create_new(true).open(root.join(format!("sustained-result-{}.json",std::process::id()))).unwrap();serde_json::to_writer_pretty(f,&result).unwrap();assert_eq!(result["footer"]["observation_complete"],true);assert_eq!(result["events"],36001);
}
fn observer_scoped(capture:Arc<super::super::scoped::ScopedCapture>)->Observer{Observer{tap:Capture::Scoped(capture),epoch:AtomicU64::new(1),streams:Mutex::new(Vec::new())}}
